  // ——— Assistant ———
  "Bienvenue dans iBox": "Welcome to iBox",
  "Tous vos jeux, consoles et PC, réunis dans une seule bibliothèque. Quelques étapes pour tout mettre en place — chacune peut être passée et modifiée plus tard dans les Paramètres.": "All your games, consoles and PC, together in one library. A few steps to set everything up — each one can be skipped and changed later in Settings.",
  "Vos dossiers": "Your folders",
  "lus, jamais modifiés": "read, never modified",
  "Vos émulateurs": "Your emulators",
  "détectés sur ce PC": "detected on this PC",
  "Les jaquettes": "The covers",
  "récupérées automatiquement": "fetched automatically",
  "Passer la configuration": "Skip setup",
  "Votre profil": "Your profile",
  "Votre nom et votre avatar apparaissent sur l'accueil et, si vous utilisez iNetbox, chez vos amis.": "Your name and avatar appear on the home screen and, if you use iNetbox, to your friends.",
  "Choisir un avatar et une couleur": "Choose an avatar and a color",
  "Où sont vos jeux ?": "Where are your games?",
  "Ajoutez les dossiers qui contiennent vos jeux de console. iBox les lit sans jamais les déplacer ni les modifier.": "Add the folders that contain your console games. iBox reads them without ever moving or modifying them.",
  "iBox cherche les émulateurs déjà installés sur ce PC ; ajoutez-en d'autres si besoin. Rien n'est téléchargé à votre place.": "iBox looks for emulators already installed on this PC; add others if needed. Nothing is downloaded for you.",
  "Vos jeux PC": "Your PC games",
  "Les jeux installés de Steam, Epic, GOG, EA, Ubisoft, Xbox et Riot sont trouvés tout seuls. Deux clés gratuites ajoutent plus — elles restent dans le coffre de Windows, jamais en clair.": "Installed games from Steam, Epic, GOG, EA, Ubisoft, Xbox and Riot are found on their own. Two free keys add more — they stay in the Windows vault, never in plain text.",
  "Ajoute aussi vos jeux Steam possédés mais non installés (et ceux de la Famille Steam).": "Also adds Steam games you own but haven't installed (and Steam Family ones).",
  "Ouvrez la page Steam (connectez-vous à votre compte).": "Open the Steam page (sign in to your account).",
  "Nom de domaine : tapez « localhost », acceptez les conditions, puis « Enregistrer ».": "Domain name: type “localhost”, accept the terms, then “Register”.",
  "Copiez la clé affichée et collez-la ici.": "Copy the key shown and paste it here.",
  "Dans Steam › Profil › Modifier › Confidentialité, mettez « Détails des jeux » sur Public.": "In Steam › Profile › Edit › Privacy, set “Game details” to Public.",
  "Clé SteamGridDB": "SteamGridDB key",
  "Jaquettes, logos et fonds pour les jeux PC, Switch et Switch 2.": "Covers, logos and backgrounds for PC, Switch and Switch 2 games.",
  "Ouvrez la page SteamGridDB et connectez-vous (avec Steam, c'est le plus simple).": "Open the SteamGridDB page and sign in (with Steam is easiest).",
  "Cliquez sur « Generate API Key ».": "Click “Generate API Key”.",
  "Copiez la clé et collez-la ici.": "Copy the key and paste it here.",
  "Ouvrir la page": "Open the page",
  "iBox et Windows": "iBox and Windows",
  "Comme un lanceur de jeux : iBox s'efface pendant que vous jouez et reste disponible dans la zone de notification.": "Like a game launcher: iBox steps aside while you play and stays available in the notification area.",
  "Tout est prêt": "All set",
  "Étape {0} sur {1}": "Step {0} of {1}",

  "Choisir le dossier Steam": "Choose the Steam folder",
  "Sélectionnez le dossier qui contient steam.exe.": "Select the folder that contains steam.exe.",
