  "Le bouton de recherche rapide est indiqué en bas à droite de l’accueil.": "The quick search button is shown at the bottom right of the home screen.",
  "Filtrez vos jeux automatiquement et prévisualisez la carte pendant sa personnalisation.": "Filter your games automatically and preview the card while customizing it.",
  "Retrouvez les jeux, consoles et collections depuis l’accueil, même à la manette.": "Find games, consoles and collections from the home screen, even with a controller.",
  "Comparez vos jeux avec ceux d’un ami et personnalisez votre profil avec une bannière et trois jeux favoris.": "Compare your games with a friend's and personalize your profile with a banner and three favorite games.",
