  // ——— Steam Deck ———
  "Fonction expérimentale. Rejoignez la partie d'un ami qui joue sur un PC iBox sous Windows : le jeu tourne chez lui, vous jouez avec la manette du Steam Deck. Le Steam Deck rejoint des parties mais n'en partage pas.": "Experimental feature. Join a friend's game running on a Windows PC with iBox: the game runs on their PC and you play with the Steam Deck controller. The Steam Deck joins games but does not share its own.",
  "Expérimental, désactivé par défaut. Désactivé, aucune recherche d'invitations ne tourne.": "Experimental, off by default. When off, iBox does not look for invitations.",
  "Activé, vos amis iNetbox peuvent vous inviter ; vous acceptez ou refusez chaque invitation.": "When on, your iNetbox friends can invite you; you accept or decline each invitation.",
  "Disponible : l'image de l'hôte est décodée par ce Steam Deck.": "Available: this Steam Deck decodes the host's picture.",
  "Indisponible : cette version d'iBox ne sait pas décoder l'image H.264 de l'hôte.": "Unavailable: this version of iBox cannot decode the host's H.264 picture.",
  "Sur Steam Deck, iBox rejoint une partie mais n'en héberge pas.": "On Steam Deck, iBox joins games but does not host them.",
  "Les jeux Steam installés sont trouvés tout seuls. Des clés gratuites ajoutent plus.": "Installed Steam games are found on their own. Free keys add more.",
  "Sur Steam Deck, les captures se font avec Steam (bouton Steam + R1).": "On Steam Deck, screenshots are taken with Steam (Steam button + R1).",
  "Pas d’installation automatique sur Steam Deck pour cet émulateur. Installez-le avec Discover (Flatpak), EmuDeck ou son AppImage officielle, puis utilisez « Rechercher les émulateurs installés » (Paramètres › PC et émulateurs).": "No automatic install on Steam Deck for this emulator. Install it with Discover (Flatpak), EmuDeck or its official AppImage, then use “Search for installed emulators” (Settings › PC and emulators).",
  "Choisissez le dossier de Steam (celui qui contient steamapps).": "Pick the Steam folder (the one that contains steamapps).",
