  "En pleine partie, Alt+E ouvre l’overlay iBox : gardez une capture d’écran, un clip des 12 dernières secondes, puis partagez-les avec vos amis dans la Communauté.": "Mid-game, Alt+E opens the iBox overlay: keep a screenshot or a clip of the last 12 seconds, then share them with your friends in the Community.",
  "Chaque joueur chez soi": "Every player at home",
  "Changez d’utilisateur depuis l’accueil. Chaque profil a son compte iNetbox, ses fonds, son thème et ses réglages ; seuls les jeux restent communs.": "Switch users from the home screen. Each profile has its own iNetbox account, backgrounds, theme and settings; only the games are shared.",
  "Compte par e-mail": "Email accounts",
  "L’inscription demande une adresse e-mail ; on peut se connecter avec, et réinitialiser un mot de passe oublié grâce à un code reçu par e-mail.": "Sign-up asks for an email address; you can sign in with it, and reset a forgotten password with a code sent by email.",
  "Jusqu’à 8 manettes": "Up to 8 controllers",
  "De P1 à P8 : à partir de trois manettes, une pastille compacte « P1,2 +N » déplie la liste complète.": "From P1 to P8: from three controllers on, a compact “P1,2 +N” chip expands the full list.",
  "Jaquettes en plein écran": "Full-screen covers",
  "En faisant défiler la grille, tout le haut de l’écran s’efface en douceur ; il revient dès que vous remontez.": "Scrolling the grid smoothly fades out the whole top of the screen; it comes back as soon as you scroll up.",
