  "Jeux PC en boîtier 3D": "PC games in a 3D case",
  "Comme sur console, chaque jeu PC a son boîtier DVD en 3D sur sa fiche : faites-le tourner, ouvrez-le, regardez le dos, la tranche et sortez le disque imprimé à son image.": "Just like on consoles, every PC game now has its own 3D DVD case on its page: spin it, open it, look at the back and spine, and take out the disc printed with its artwork.",
  "Jaquettes PC soignées": "Polished PC covers",
  "Bandeau « PC DVD-ROM » et boutique sur la face, dos sombre avec la bannière, le résumé et les captures du jeu, disque avec son logo.": "“PC DVD-ROM” band and store on the front, a dark back with the game's banner, summary and screenshots, and a disc with its logo.",
  "Jeu déjà lancé reconnu": "Already running game recognised",
  "Ajoutez un jeu PC pendant qu’il tourne : iBox le considère aussitôt comme lancé (temps de jeu, Alt+E), sans le relancer.": "Add a PC game while it's running: iBox treats it as launched right away (playtime, Alt+E), no restart needed.",
  "Adresse e-mail lisible": "Readable email address",
  "La ligne « Adresse e-mail » du compte iNetbox se lit enfin en mode sombre.": "The “Email address” row of your iNetbox account is now readable in dark mode.",
  "Glisser pour tourner": "Drag to rotate",
  "Stick droit pour tourner": "Right stick to rotate",
  "Réactions et commentaires": "Reactions and comments",
  "Dans la Communauté, réagissez aux partages de vos amis avec un émoji et commentez-les, avec des petits mots tout prêts.": "In the Community, react to your friends' shares with an emoji and comment on them, with ready-made quick replies.",
  "Onglet Amis repensé": "Friends tab redesigned",
  "Votre carte est plus claire : statut en un geste, trois réglages bien rangés (partie, jeux, ne pas déranger) et de grands boutons ronds ; plus de texte illisible en mode sombre.": "Your card is clearer: status in one tap, three tidy settings (game, games, do not disturb) and big round buttons; no more unreadable text in dark mode.",
  "Alt+E partout": "Alt+E everywhere",
  "L’overlay de capture s’ouvre même quand iBox ne détecte aucun jeu : capturez n’importe quoi à l’écran.": "The capture overlay opens even when iBox detects no game: capture anything on screen.",
  "Salle des trophées ajustée": "Trophy room tweaks",
  "Votre nom n’est plus caché par le bandeau, et la pastille de niveau est plus discrète.": "Your name is no longer hidden by the banner, and the level badge is more discreet.",
