  "{0} · {1}": "{0} · {1}",
  "Remote Play nécessite Windows.": "Remote Play requires Windows.",
  "Périphériques audio : {0}": "Audio devices: {0}",
  "Bouton « Remote Play » sur chaque jeu": "“Remote Play” button on every game",
  "Sur la fiche d’un jeu, « Remote Play » choisit un ami iNetbox, règle ses droits (Joueur par défaut) et lance le jeu, sans passer par les paramètres. Remote Play s’active depuis ce menu.": "On a game page, “Remote Play” picks an iNetbox friend, sets their rights (Player by default) and launches the game, without going through the settings. Remote Play can be turned on from this menu.",
  "Manette de l’ami reconnue": "Friend's controller recognized",
  "La manette de l’invité est bien transmise et apparaît comme une manette de plus sur l’hôte (P2 si l’hôte joue déjà). Session d’essai : droits « Joueur » par défaut.": "The guest's controller is now passed through and shows up as one more controller on the host (P2 if the host is already playing). Test session: “Player” rights by default.",
  "Lisibilité en mode sombre": "Easier to read in dark mode",
  "Commentaires des captures Communauté et résultats du diagnostic Remote Play bien lisibles en mode sombre ; nombreuses traductions anglaises ajoutées (profil, collections, sauvegardes…).": "Community capture comments and Remote Play check results are easy to read in dark mode; many English translations added (profile, collections, backups…).",
  "Boîtes de cartouches réparées": "Cartridge boxes fixed",
  "L’intérieur de la boîte ouverte est visible et le rabat ne se mélange plus à la jaquette en se refermant.": "The inside of the open box is visible and the flap no longer blends into the cover when it closes.",
  "Manette de l’invité connectée d’office": "Guest controller connected automatically",
  "En Remote Play, la manette de votre ami est détectée et envoyée toute seule dès qu’il la branche et appuie sur un bouton, sans rien cliquer. Son nom s’affiche en bas de l’écran.": "In Remote Play, your friend’s controller is detected and sent on its own as soon as they plug it in and press a button, with nothing to click. Its name shows at the bottom of the screen.",
  "Pilote manette installé en un clic": "Controller driver installed in one click",
  "Sur l’hôte, la manette de l’invité a besoin du pilote ViGEmBus. S’il manque, iBox propose de l’installer (Windows demande votre accord) et la manette se branche aussitôt, sans relancer la session. Aussi dans Paramètres › Remote Play.": "On the host, the guest’s controller needs the ViGEmBus driver. If it is missing, iBox offers to install it (Windows asks for your approval) and the controller connects right away, without restarting the session. Also in Settings › Remote Play.",
  "Bandeau de partage réductible": "Collapsible sharing banner",
  "Le bandeau « Partage en cours avec » se réduit en une petite pastille dans le coin de l’écran ; un clic dessus le rouvre.": "The “Sharing with” banner collapses into a small dot in the corner of the screen; click it to open it again.",
  "Afficher le bandeau Remote Play": "Show the Remote Play banner",
  "Réduire en pastille": "Collapse to a dot",
  "Activer la manette": "Enable controller",
  "Installe le pilote ViGEmBus pour la manette de votre invité": "Installs the ViGEmBus driver for your guest’s controller",
  "Installation du pilote manette…": "Installing controller driver…",
  "Rendre le clavier et la souris": "Give keyboard and mouse back",
  "Envoyer clavier et souris": "Send keyboard and mouse",
  "Manette connectée :": "Controller connected:",
  "Manette : branchez-la et appuyez sur un bouton": "Controller: plug it in and press a button",
  "Pilote ViGEmBus absent : nécessaire pour que la manette de votre invité fonctionne (Windows demandera votre accord)": "ViGEmBus driver missing: needed for your guest’s controller to work (Windows will ask for your approval)",
  "installation refusée dans l'invite de Windows": "installation declined in the Windows prompt",
  "l'installeur téléchargé ne correspond pas à la version attendue : installation annulée": "the downloaded installer does not match the expected version: installation cancelled",
