  "{0} joueurs sur 6 au plus": "{0} players out of 6 max",
  "Inviter un ami de plus": "Invite one more friend",
  "Voir la publication": "View the post",
  "{0} vous a mentionné dans une capture": "{0} mentioned you in a capture",
  "{0} vous a mentionné dans un commentaire": "{0} mentioned you in a comment",
  "Sur une fenêtre de jeu, sa souris et son clavier restent confinés à cette fenêtre (ignorés quand elle n'est pas au premier plan).": "On a game window, their mouse and keyboard stay confined to that window (ignored when it is not in the foreground).",
  "La partie est complète : {0} invités au plus, soit 6 joueurs avec vous.": "The party is full: {0} guests max, 6 players including you.",
  "Cet ami est déjà dans la partie.": "This friend is already in the party.",
  "Remote Play jusqu’à 6 joueurs": "Remote Play for up to 6 players",
  "Invitez jusqu’à 5 amis dans la même partie : chacun a sa connexion directe et sa manette, branchée d’office comme une manette de plus sur l’hôte. « Inviter un ami de plus » depuis la carte de partage.": "Invite up to 5 friends into the same party: each gets a direct connection and their own controller, plugged in automatically as one more controller on the host. Use “Invite one more friend” on the sharing card.",
  "Collaborateur : la souris répond": "Collaborator: the mouse responds",
  "Sur la fenêtre d’un jeu, l’invité Collaborateur contrôle enfin souris et clavier, confinés à cette fenêtre (raccourcis système bloqués). Quand l’hôte arrête, l’invité revient aussitôt à iBox.": "On a game window, a Collaborator guest now controls the mouse and keyboard, confined to that window (system shortcuts blocked). When the host stops, the guest returns to iBox right away.",
  "Plus rapide, plus de cartes graphiques": "Faster, more graphics cards",
  "Latence réduite (capture au plus près, encodeur en mode faible latence) et encodeurs AMD et Intel mieux pris en charge, y compris sur les PC à deux cartes graphiques.": "Lower latency (tighter capture, low-latency encoder mode) and better AMD and Intel encoder support, including on PCs with two graphics cards.",
  "Communauté plus vivante": "A livelier Community",
  "Mentionnez un ami avec @ dans une légende ou un commentaire (il reçoit une notification), répondez aux commentaires, et profitez d’animations plus soignées.": "Mention a friend with @ in a caption or comment (they get a notification), reply to comments, and enjoy smoother animations.",
  "Succès instantanés": "Instant achievements",
  "L’écran Succès s’ouvre déjà rempli avec vos dernières données, puis se met à jour en arrière-plan.": "The Achievements screen opens already filled with your latest data, then updates in the background.",
  "Nouveau logo, nouvelle musique": "New logo, new music",
  "iBox adopte son nouveau logo et une musique de menu originale, composée pour iBox. Au premier lancement, l’accueil montre « Votre dernière aventure » ; le dossier des jeux se choisit dans les Paramètres.": "iBox gets its new logo and an original menu theme composed for iBox. On first launch, Home shows “Your last adventure”; the games folder is chosen in Settings.",
  "Plus d’écho Discord": "No more Discord echo",
  "En appel Discord pendant une session, votre ami n’entend plus sa propre voix renvoyée : le son de Discord est retiré de ce qui lui est envoyé (Paramètres › Remote Play, activé par défaut).": "On a Discord call during a session, your friend no longer hears their own voice echoed back: Discord’s audio is removed from what is sent to them (Settings › Remote Play, on by default).",
