  "Votre jeu est presque prêt. Installez l'émulateur recommandé pour cette console : iBox l'associera tout seul, puis revenez jouer.": "Your game is almost ready. Install the recommended emulator for this console: iBox will link it automatically, then come back to play.",
  "Voir l'émulateur recommandé": "See the recommended emulator",
  "Installez un émulateur depuis iBox Platforms, ou indiquez ceux déjà présents sur ce PC. Le profil de lancement (Dolphin, PCSX2, melonDS…) est reconnu automatiquement et reste modifiable. Les jeux sont lancés sans passer par une ligne de commande : un nom de fichier ne peut rien déclencher d'autre.": "Install an emulator from iBox Platforms, or point iBox to the ones already on this PC. The launch profile (Dolphin, PCSX2, melonDS…) is recognised automatically and stays editable. Games are launched without a command line: a file name cannot trigger anything else.",
