  "Émulateur PSP rapide et soigné, disponible depuis plus de dix ans.": "A fast, polished PSP emulator, around for over ten years.",
  "Il fait tourner la quasi-totalité de la ludothèque PSP, en haute définition, même sur un PC modeste.": "It runs nearly the whole PSP library in high definition, even on a modest PC.",
  "Émulateur PlayStation axé sur la précision et le confort.": "A PlayStation emulator focused on accuracy and comfort.",
