  "Émulateur Wii U, devenu libre en 2022.": "A Wii U emulator, open source since 2022.",
  "Le seul émulateur Wii U mûr ; la plupart des grands jeux y sont jouables.": "The only mature Wii U emulator; most major games are playable.",
