  "Le fichier de réglages de ce jeu a changé depuis la dernière optimisation (par vous ou par l'émulateur). L'appliquer quand même remplacera ces changements ; la sauvegarde de l'état actuel reste possible à restaurer.": "This game's settings file changed since the last optimization (by you or by the emulator). Applying anyway replaces those changes; the current state is backed up and can be restored.",
