  "Seulement les configurations les plus sûres : machine très proche, jeu identifié par son numéro de série, réglages à faible risque, très bonnes performances. Les jeux reconnus par leur seul titre ne sont jamais concernés.": "Only the safest configurations: a very close machine, a game identified by its serial number, low-risk settings, very good performance. Games recognized by title alone are never affected.",
