  "Vous l'avez appliqué puis indiqué qu'il ne fonctionnait pas : il n'est plus proposé pour ce jeu.": "You applied it and said it didn't work: it's no longer offered for this game.",
  "Vous l'aviez signalé comme ne fonctionnant pas avec une autre version de l'émulateur : rétrogradé.": "You reported it as not working with another emulator version: ranked lower.",
