  "Essayé en jeu par l'équipe iBox sur le matériel indiqué, puis relu.": "Tried in game by the iBox team on the listed hardware, then reviewed.",
  "Profils essayés en jeu par l'équipe iBox sur un matériel et une version d'émulateur précis, puis relus. Livrés avec iBox.": "Profiles tried in game by the iBox team on specific hardware and emulator versions, then reviewed. Shipped with iBox.",
  "Rien : les profils sont inclus dans l'application.": "Nothing: the profiles are included in the app.",
  "{0} : réglages par jeu pas encore pris en charge sous Linux": "{0}: per-game settings not supported on Linux yet",
  "dossier personnel introuvable": "home folder not found",
  "Vos amis en un coup d’œil": "Your friends at a glance",
  "Le bouton Amis de la barre du haut affiche maintenant les photos de vos amis, ceux en ligne en premier, avec leur pastille de présence et le nombre des autres.": "The Friends button in the top bar now shows your friends’ pictures, online ones first, with their presence dot and a count of the others.",
  "Un accueil plus sobre": "A cleaner Home",
  "Les boutons de « Mes collections » se résument à leur icône, la ligne du nombre de plateformes disparaît, et le bouton pour changer d’utilisateur passe à gauche de votre profil.": "The “My collections” buttons are now icons only, the platform count line is gone, and the switch-user button moves to the left of your profile.",
  "Des boutons aux couleurs de votre thème": "Buttons in your theme’s colors",
  "Boutons et icônes de toute l’app prennent maintenant les couleurs du thème choisi, tout en douceur ; les thèmes volontairement vifs, comme Bonbon et Agrume, gardent leur éclat.": "Buttons and icons across the app now take on the colors of your chosen theme, gently; deliberately bold themes such as Bonbon and Agrume keep their punch.",
  "iBox Platforms en verre": "Glass iBox Platforms",
  "La tuile « iBox Platforms » de l’accueil devient une plaque de verre dépoli, translucide et plus douce, teintée par votre thème.": "The “iBox Platforms” tile on Home becomes a pane of frosted glass, translucent and softer, tinted by your theme.",
  "Un fond d’accueil plus doux": "A softer Home background",
  "Le grand fond de l’accueil est légèrement flouté pour laisser respirer les cases. Et « Votre dernière aventure » affiche toujours l’image du jeu, même sans grande illustration.": "The large Home background is slightly blurred to give the tiles room to breathe. And “Your last adventure” always shows the game’s image, even without large artwork.",
  "Votre collection bien en vue": "Your collection in plain sight",
  "Le jeu mis en avant derrière l’étagère de « Ma collection » ressort enfin : voile allégé, image plus nette et plus colorée. « Votre dernière aventure » laisse aussi bien mieux voir l’image du jeu, sous un voile de couleur bien plus léger.": "The game featured behind the “My collection” shelf finally stands out: a lighter veil and a sharper, more colorful image. “Your last adventure” also shows much more of the game’s image, under a far lighter color veil.",
  "Des visages d’amis plus nets": "Clearer friend faces",
  "Les photos du bouton Amis sont un peu plus grandes, cerclées et ne se mélangent plus quand elles se chevauchent.": "The photos on the Friends button are a little larger, outlined, and no longer blend together where they overlap.",
  "Une étagère tout en douceur": "A smoother shelf",
  "Dans « Ma collection », les jaquettes apparaissent et s’effacent désormais en fondu sur le bord gauche de l’étagère, comme à droite, au lieu d’être coupées net.": "In “My collection”, covers now fade in and out at the left edge of the shelf, just like on the right, instead of being cut off sharply.",
