  "PNG ou WebP transparents et GIF animés rendent le mieux.": "Transparent PNG or WebP and animated GIFs look best.",
  "Confirmer la suppression": "Confirm removal",
  "Pokémon (ex. Pikachu, Évoli, Lucario)": "Pokémon (e.g. Pikachu, Eevee, Lucario)",
  "Chercher un Pokémon": "Search for a Pokémon",
