  "Encodage impossible": "Encoding failed",
  "Le catalogue Riot ne contient aucune icône lisible.": "The Riot catalog has no readable icon.",
  "Aucune version Data Dragon disponible.": "No Data Dragon version available.",
  "Réponse WebRTC indisponible": "WebRTC answer unavailable",
  "Évoli": "Eevee",
  "Salamèche": "Charmander",
  "iBox parle anglais jusqu’au bout": "iBox speaks English all the way",
  "Les derniers textes restés en français dans l’interface anglaise sont traduits : consoles sans jeux, boutiques PC, sauvegarde de la collection, émulateurs, Remote Play et plus encore.": "The last French texts left in the English interface are translated: consoles without games, PC stores, collection backup, emulators, Remote Play and more.",
  "Des Paramètres plus légers": "Lighter Settings",
  "L’écran Paramètres est réorganisé en coulisses, une partie par catégorie : il reste aussi rapide à ouvrir et sera plus simple à faire évoluer.": "The Settings screen is reorganized behind the scenes, one part per category: it opens just as fast and will be easier to improve.",
  "Tous vos jeux PC sont réunis dans une seule bibliothèque, quelle que soit leur boutique. iBox ne demande jamais vos mots de passe et ne contourne aucune protection ; vos jeux ne sont ni déplacés ni modifiés.": "All your PC games in one library, whatever the store. iBox never asks for your passwords and never bypasses any protection; your games are neither moved nor modified.",
  "{0} jeu{1} PC dans la bibliothèque": "{0} PC game{1?s} in the library",
  "Les jeux installés de Steam, Epic, GOG, EA, Ubisoft, Xbox et Riot sont trouvés tout seuls. Des clés gratuites ajoutent plus — elles restent dans le coffre de Windows, jamais en clair.": "Installed games from Steam, Epic, GOG, EA, Ubisoft, Xbox and Riot are found automatically. Free keys add more — they stay in the Windows vault, never in plain text.",
  "Bibliothèque, collections, réglages et jingles personnels dans un fichier. Sur un autre PC, ajoutez de nouveau les dossiers de jeux si leur emplacement a changé.": "Library, collections, settings and personal jingles in one file. On another PC, add your game folders again if their location changed.",
  "Complète ce qui manque (jaquette, logo, fond) avec les images iiDB, en préférant celles de la console du jeu. Aucune image existante n'est remplacée : pour en changer une, ouvrez « Illustrations » sur la fiche du jeu, où iiDB apparaît désormais.": "Fills in what is missing (cover, logo, background) with iiDB images, preferring those of the game's console. No existing image is replaced: to change one, open “Artwork” on the game's page, where iiDB now appears.",
  // ——— 0.1.93 : grille libre, décorations animées ———
  "Vos collections où vous voulez": "Your collections wherever you like",
  "Avec Organiser, chaque collection ou décoration se pose dans la case de votre choix, même s’il reste des cases vides avant elle. Lâchée sur une autre carte, les deux échangent leur place.": "With Arrange, every collection or decoration goes into the slot of your choice, even with empty slots before it. Dropped on another card, the two swap places.",
  "Un glisser tout en douceur": "Smooth dragging",
  "La carte attrapée suit maintenant la souris sans se dédoubler, puis glisse d’elle-même dans sa nouvelle case.": "The card you grab now follows the mouse without doubling up, then glides into its new slot on its own.",
  "Encore plus de décorations mignonnes": "Even more cute decorations",
  "Plus de 80 émojis animées (animaux, frimousses, étoiles, gourmandises…) rejoignent les Pokémon, qui passent eux aussi à 40, dont toute la famille d’Évoli.": "Over 80 animated emojis (animals, faces, stars, treats…) join the Pokémon, now 40 of them too, including the whole Eevee family.",
  "Des boutons cohérents": "Consistent buttons",
  "Les boutons des collections prennent la même forme que la barre de l’accueil : des icônes seules, avec leur nom en bulle au survol, qui ne se cache plus jamais derrière une carte.": "The collection buttons now match the home bar: icons only, with their name in a bubble on hover that never hides behind a card again.",
  "Organiser : maintenez le clic sur une carte et posez-la dans la case de votre choix": "Arrange: hold the click on a card and drop it in the slot of your choice",
  "Émojis animées": "Animated emojis",
  "Émojis animées Noto de Google, transparentes. Choisissez-en une pour la voir bouger.": "Google’s transparent Noto animated emojis. Pick one to see it move.",
