  "Le lecteur reste à l’écran pendant que vous jouez : le jeu garde le clavier et la manette, et les clics à côté du lecteur vont au jeu. Le raccourci le referme.": "The player stays on screen while you play: the game keeps the keyboard and controller, and clicks next to the player go to the game. The shortcut closes it.",
