  "Maintenez Vue et Y une demi-seconde, sur n’importe quelle manette.": "Hold View and Y for half a second, on any controller.",
  "Vue + Y": "View + Y",
  "Position à l’écran": "Position on screen",
  "Faites glisser le lecteur où vous voulez. Il reste à cet endroit quand il s’agrandit pour les playlists ou la recherche, sans jamais sortir de l’écran.": "Drag the player wherever you like. It stays there when it grows for playlists or search, and never leaves the screen.",
