  // Journal de jeu
  "Journal": "Journal",
  "Journal de jeu": "Play journal",
  "Voir le détail de vos parties": "See your sessions in detail",
  "Aucune partie notée pour l'instant": "No session recorded yet",
  "Lancez ce jeu depuis iBox : chaque partie s'inscrira ici, avec sa date et sa durée.": "Launch this game from iBox: every session will be listed here, with its date and length.",
