  "Seules les parties lancées depuis iBox sont notées.": "Only sessions launched from iBox are recorded.",

  // Notes de la version 1.0.3
  "Une recherche qui trouve tout": "A search that finds everything",
  "La recherche (touche /, bouton Select) retrouve vos jeux avec leur jaquette, les consoles, vos collections, les pages des Paramètres et des actions. Elle comprend les initiales (« mk8 »), les sigles (« GC ») et une faute de frappe. Entrée ouvre le meilleur résultat, X lance le jeu.": "Search (the / key, the Select button) now finds your games with their cover, consoles, your collections, Settings pages and actions. It understands initials (“mk8”), short names (“GC”) and a typo. Enter opens the best result, X launches the game.",
  "Au hasard : iBox choisit pour vous": "Random: iBox picks for you",
  "Sur l’étagère 3D, le bouton Au hasard (touche R) fait défiler les boîtiers jusqu’à un jeu tiré au sort, qui fait un tour sur lui-même. Aussi depuis l’accueil, le menu rapide et la recherche.": "On the 3D shelf, the Random button (R key) riffles through the cases until it lands on a game drawn at random, which spins once. Also from the home screen, the quick menu and search.",
  "Un journal de jeu sur chaque fiche": "A play journal on every game page",
  "La pastille Journal d’une fiche ouvre le détail de vos parties : temps total, plus longue partie, rythme des douze dernières semaines, puis les parties une à une. La bibliothèque gagne le tri Joués récemment.": "The Journal chip on a game page opens your sessions in detail: total time, longest session, the pace of the last twelve weeks, then every session one by one. The library gains a Recently played sort.",
  "Votre musique jusque dans iBox": "Your music, right inside iBox",
  "Avec le plugin Music in the Box, le titre en cours s’affiche dans la barre du haut (lecture, pause, suivant) et la musique des menus se tait tant que la vôtre joue. Le panneau gagne les paroles, une radio à partir d’un titre et un démarrage rapide quand rien ne joue.": "With the Music in the Box plugin, the song that is playing shows in the top bar (play, pause, next) and the menu music stays quiet while yours plays. The panel gains lyrics, a radio started from a song, and a quick start when nothing is playing.",
  "Corrections": "Fixes",
  "Les liens vers les Paramètres ouvrent la bonne page. Une partie lancée après minuit compte pour le bon jour dans les statistiques, et la série de jours n’est plus limitée à 60. Dans le panneau musique, on avance dans un titre au clavier et à la manette.": "Links to Settings open the right page. A session started after midnight counts for the right day in the statistics, and the day streak is no longer capped at 60. In the music panel, you can seek within a song with the keyboard and the controller.",

  // Music in the Box : paroles, radio, démarrage rapide, « En cours » dans iBox
  "Paroles": "Lyrics",
  "Radio de ce titre": "Radio for this song",
  "Des titres proches, à la suite, sans fin": "Similar songs, one after another, endlessly",
  "Remplace la file par des titres proches de celui-ci, sans fin": "Replaces the queue with songs close to this one, endlessly",
  "Lancer la radio de l’artiste": "Start the artist's radio",
  "Aucun titre en cours": "Nothing is playing",
  "Lancez un titre sur YouTube Music : ses paroles s’afficheront ici.": "Play a song on YouTube Music: its lyrics will show up here.",
  "Paroles indisponibles": "Lyrics unavailable",
  "Mettez à jour le plugin Music in the Box (Paramètres › Plugins) pour afficher les paroles.": "Update the Music in the Box plugin (Settings › Plugins) to show lyrics.",
  "YouTube Music n’a pas répondu. Réessayez dans un instant.": "YouTube Music did not answer. Try again in a moment.",
  "Pas de paroles pour ce titre": "No lyrics for this song",
  "YouTube Music n’en propose pas : c’est souvent le cas des morceaux instrumentaux.": "YouTube Music has none for it: that is often the case with instrumental tracks.",
